mapper.select:
SELECT r.id, r.paper_id AS paperId, p.title AS paperTitle, r.user_id AS userId, u.nickname, r.score, r.objective_score AS objectiveScore, r.subjective_score AS subjectiveScore, r.status, r.start_time AS startTime, r.submit_time AS submitTime, p.total_score AS totalScore, p.pass_score AS passScore FROM exam_record r JOIN paper p ON p.id = r.paper_id JOIN sys_user u ON u.id = r.user_id
AND r.paper_id = #{paperId} AND r.user_id = #{userId}
ORDER BY r.start_time DESC
